    int total = 0;
    for (int stone : stones) total += stone;
    int capacity = total / 2;
    Integer[][] memo = new Integer[stones.length][capacity + 1];
    int best = bestSubset(stones, 0, capacity, memo);
    return total - 2 * best;
  }

  private int bestSubset(int[] stones, int index, int capacity, Integer[][] memo) {
    if (index == stones.length || capacity == 0) return 0;
    if (memo[index][capacity] != null) return memo[index][capacity];
    int skip = bestSubset(stones, index + 1, capacity, memo);
    int take = 0;
    if (stones[index] <= capacity) {
      take = stones[index] + bestSubset(stones, index + 1, capacity - stones[index], memo);
    }
    memo[index][capacity] = Math.max(skip, take);
    return memo[index][capacity];
  }
}

