    return dp(nums, 0, total / 2, memo);
  }

  private boolean dp(int[] nums, int index, int target, Boolean[][] memo) {
    if (target == 0) return true;
    if (index == nums.length || target < 0) return false;
    if (memo[index][target] != null) return memo[index][target];
    boolean skip = dp(nums, index + 1, target, memo);
    boolean take = target >= nums[index] && dp(nums, index + 1, target - nums[index], memo);
    memo[index][target] = skip || take;
    return memo[index][target];
  }
}

