class Solution {
  private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

  public int longestIncreasingPath(int[][] matrix) {
    int rows = matrix.length;
    int cols = matrix[0].length;
    int[][] memo = new int[rows][cols];
    int best = 0;
    for (int row = 0; row < rows; row++) {
      for (int col = 0; col < cols; col++) {
        best = Math.max(best, dp(matrix, row, col, memo));
      }
    }
    return best;
  }

  private int dp(int[][] matrix, int row, int col, int[][] memo) {
    if (memo[row][col] != 0) return memo[row][col];
    int best = 1;
    for (int[] dir : DIRS) {
      int nextRow = row + dir[0];
      int nextCol = col + dir[1];
      if (nextRow < 0 || nextCol < 0 || nextRow == matrix.length || nextCol == matrix[0].length) continue;
      if (matrix[nextRow][nextCol] > matrix[row][col]) {
        best = Math.max(best, 1 + dp(matrix, nextRow, nextCol, memo));
      }
    }
    memo[row][col] = best;
    return best;
  }
}

