import java.util.*;

class Solution {
  private int bestSide;

  public int maximalSquare(char[][] matrix) {
    int rows = matrix.length;
    int cols = matrix[0].length;
    int[][] memo = new int[rows][cols];
    for (int[] row : memo) Arrays.fill(row, -1);
    for (int row = 0; row < rows; row++) {
      for (int col = 0; col < cols; col++) {
        bestSide = Math.max(bestSide, dp(matrix, row, col, memo));
      }
    }
    return bestSide * bestSide;
  }

  private int dp(char[][] matrix, int row, int col, int[][] memo) {
    if (row == matrix.length || col == matrix[0].length) return 0;
    if (memo[row][col] != -1) return memo[row][col];
    int down = dp(matrix, row + 1, col, memo);
    int right = dp(matrix, row, col + 1, memo);
    int diagonal = dp(matrix, row + 1, col + 1, memo);
    memo[row][col] = matrix[row][col] == '1' ? 1 + Math.min(down, Math.min(right, diagonal)) : 0;
    return memo[row][col];
  }
}
